pub fn is_palindrome(text: Vec<char>) -> bool {
    let n = text.len();
    for i in 0..n / 2 {
        if text[i].to_ascii_lowercase() != text[n - 1 - i].to_ascii_lowercase() {
            return false;
        }
    }
    true
}

